c.STDIO:
#include <stdio.h>

int main(void) {
    long long left, right, step;
    scanf("%lld%lld%lld", &left, &right, &step);
    long long answer = right / step;
    if (left == 0) {
        answer++;
    } else {
        answer -= (left - 1) / step;
    }
    printf("%lld\n", answer);
    return 0;
}

